"use client";

import * as React from "react";
import { Button as ButtonPrimitive } from "@base-ui/react/button";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";
import { pressDestructive, pressOutline, pressPrimary, pressSecondary } from "./_shared";

/**
 * Playful console Button on a Base UI button: a chunky key that presses.
 *
 * Every solid button is a bordered face on an offset slab. It lifts under
 * the pointer and drops into the slab when pressed. The default is the
 * orange key; secondary is a white key on the orange slab; outline is a
 * white key on a cream slab. Ghost and link stay flat. A disabled button
 * loses its slab and rests on cream, whether it is a native button or a
 * link rendered through `render`.
 */
const buttonVariants = cva(
  [
    "inline-flex max-w-full shrink-0 select-none items-center justify-center gap-2 whitespace-nowrap",
    "rounded-[0.5rem] font-bold",
    "focus-visible:outline-2 focus-visible:outline-offset-3 focus-visible:outline-ring",
    "disabled:pointer-events-none disabled:translate-y-0 disabled:border-(--line-strong) disabled:bg-secondary disabled:text-(--foreground-disabled) disabled:shadow-none",
    "data-[disabled]:pointer-events-none data-[disabled]:translate-y-0 data-[disabled]:border-(--line-strong) data-[disabled]:bg-secondary data-[disabled]:text-(--foreground-disabled) data-[disabled]:shadow-none",
    "[&_svg]:pointer-events-none [&_svg]:shrink-0",
  ].join(" "),
  {
    variants: {
      variant: {
        // The orange key: the one action a screen exists to offer.
        default: pressPrimary,
        primary: pressPrimary,
        secondary: pressSecondary,
        outline: pressOutline,
        // Deep ink, flat: a strong action that should not compete with orange.
        solid:
          "bg-(--ink) text-(--ink-foreground) transition-colors duration-fast hover:bg-(--foreground-secondary)",
        ghost:
          "bg-transparent text-foreground transition-colors duration-fast hover:bg-secondary",
        destructive: pressDestructive,
        link: "h-auto rounded-sm px-0 font-semibold text-(--link) underline-offset-4 hover:underline",
      },
      size: {
        sm: "h-8 px-3 text-[0.8125rem]",
        default: "h-10 px-5 text-[0.9375rem]",
        lg: "h-12 px-6 text-base",
        icon: "size-10 px-0",
        "icon-sm": "size-8 px-0",
        "icon-lg": "size-12 px-0",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  },
);

/** Props for the Base UI Button. `asChild` turns a single child element into the button. */
export interface ButtonProps
  extends
    Omit<ButtonPrimitive.Props, "className">,
    VariantProps<typeof buttonVariants> {
  className?: string;
  /**
   * Renders the single child element as the button, for callers written
   * against the Radix API (`<Button asChild><a href="…" /></Button>`).
   * Base UI composes through `render`, so the child becomes that element.
   */
  asChild?: boolean;
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, asChild = false, children, ...props }, ref) => {
    const classes = cn(buttonVariants({ variant, size, className }));

    if (asChild && React.isValidElement(children)) {
      return (
        <ButtonPrimitive
          ref={ref}
          data-slot="button"
          className={classes}
          nativeButton={false}
          {...props}
          render={children}
        />
      );
    }

    return (
      <ButtonPrimitive ref={ref} data-slot="button" className={classes} {...props}>
        {children}
      </ButtonPrimitive>
    );
  },
);
Button.displayName = "Button";

export { Button, buttonVariants };
